import { useId, useMemo, useState, type KeyboardEvent, type PointerEvent } from 'react';
import type { Chamber, Point, Series, Snapshot, Source } from '../types';
import { useWidth } from '../hooks/useWidth';
import { SOURCE_COLOR, SOURCE_DASH, pct, pts, shortDate } from '../lib/format';

const TABS: { id: Chamber; label: string }[] = [
  { id: 'sweep', label: 'Sweep' },
  { id: 'senate', label: 'Senate' },
  { id: 'house', label: 'House' },
];
const H = 280;
const PAD = { l: 40, r: 12, t: 12, b: 26 };
const DAY = 86_400;

/** Last point at or before t (points are time-sorted). */
export function valueAt(points: readonly Point[], t: number): Point | undefined {
  let lo = 0;
  let hi = points.length - 1;
  let best: Point | undefined;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const p = points[mid]!;
    if (p.t <= t) {
      best = p;
      lo = mid + 1;
    } else hi = mid - 1;
  }
  return best;
}

/** Change over the last `days` days for a series, or null if history is too short. */
export function change(points: readonly Point[], days = 30): number | null {
  const last = points.at(-1);
  if (!last) return null;
  const prev = valueAt(points, last.t - days * DAY);
  return prev ? last.p - prev.p : null;
}

/** Multi-source time series of Democratic win probability with keyboard and pointer inspection. */
export function HistoryChart({ history, sources }: { history: Snapshot['history']; sources: readonly Source[] }) {
  const [tab, setTab] = useState<Chamber>('senate');
  const [cursor, setCursor] = useState<number | null>(null);
  const [announce, setAnnounce] = useState('');
  const [wrapRef, width] = useWidth<HTMLDivElement>();
  const baseId = useId();
  const series: Series[] = useMemo(() => history[tab].filter((s) => s.points.length > 1), [history, tab]);
  const nameOf = (id: Series['sourceId']) => sources.find((s) => s.id === id)?.name ?? id;

  const geom = useMemo(() => {
    const all = series.flatMap((s) => s.points);
    if (all.length === 0) return null;
    const t0 = Math.min(...all.map((p) => p.t));
    const t1 = Math.max(...all.map((p) => p.t));
    const pMin = Math.min(...all.map((p) => p.p));
    const pMax = Math.max(...all.map((p) => p.p));
    const y0 = Math.max(0, Math.floor((pMin - 0.05) * 10) / 10);
    const y1 = Math.min(1, Math.ceil((pMax + 0.05) * 10) / 10);
    const innerW = Math.max(10, width - PAD.l - PAD.r);
    const innerH = H - PAD.t - PAD.b;
    const x = (t: number) => PAD.l + ((t - t0) / Math.max(1, t1 - t0)) * innerW;
    const y = (p: number) => PAD.t + (1 - (p - y0) / Math.max(0.01, y1 - y0)) * innerH;
    const yTicks: number[] = [];
    for (let v = y0; v <= y1 + 1e-9; v += 0.1) yTicks.push(Math.round(v * 10) / 10);
    const xTicks: number[] = [];
    const d = new Date(t0 * 1000);
    for (let m = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 1)); m.getTime() / 1000 <= t1; m.setUTCMonth(m.getUTCMonth() + 1)) {
      xTicks.push(m.getTime() / 1000);
    }
    const tickEvery = Math.ceil(xTicks.length / Math.max(1, Math.floor(innerW / 70)));
    return { t0, t1, x, y, yTicks, xTicks: xTicks.filter((_, i) => i % tickEvery === 0), innerW };
  }, [series, width]);

  const onPointer = (e: PointerEvent<SVGSVGElement>) => {
    if (!geom) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const frac = Math.min(1, Math.max(0, (e.clientX - rect.left - PAD.l) / geom.innerW));
    setCursor(geom.t0 + frac * (geom.t1 - geom.t0));
  };
  const onKey = (e: KeyboardEvent<SVGSVGElement>) => {
    if (!geom) return;
    const cur = cursor ?? geom.t1;
    const step = e.shiftKey ? 7 * DAY : DAY;
    const next =
      e.key === 'ArrowLeft' ? cur - step : e.key === 'ArrowRight' ? cur + step : e.key === 'Home' ? geom.t0 : e.key === 'End' ? geom.t1 : null;
    if (next === null) return;
    e.preventDefault();
    const t = Math.min(geom.t1, Math.max(geom.t0, next));
    setCursor(t);
    setAnnounce(`${shortDate(t)}: ${series.map((s) => `${nameOf(s.sourceId)} ${pct(valueAt(s.points, t)?.p, 1)}`).join(', ')}`);
  };

  const readout = series.map((s) => ({ s, v: valueAt(s.points, cursor ?? Infinity) }));
  const label = series
    .map((s) => `${nameOf(s.sourceId)} ${pct(s.points.at(-1)?.p, 1)}`)
    .join(', ');

  return (
    <section aria-labelledby={`${baseId}-title`} className="panel p-5 sm:p-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <h2 id={`${baseId}-title`} className="text-lg font-semibold text-white">
          Trend
        </h2>
        <div role="tablist" aria-label="Chamber" className="inline-flex rounded-lg border border-line p-0.5 text-sm">
          {TABS.map((t) => (
            <button
              key={t.id}
              role="tab"
              type="button"
              id={`${baseId}-tab-${t.id}`}
              aria-selected={tab === t.id}
              aria-controls={`${baseId}-panel`}
              onClick={() => {
                setTab(t.id);
                setCursor(null);
              }}
              className={`rounded-md px-3 py-1.5 font-medium transition-colors ${
                tab === t.id ? 'bg-white/10 text-white' : 'text-muted hover:text-gray-200'
              }`}
            >
              {t.label}
            </button>
          ))}
        </div>
      </div>

      <ul className="mt-3 flex flex-wrap gap-x-5 gap-y-1 text-sm" aria-label="Legend">
        {readout.map(({ s, v }) => {
          const delta = change(s.points);
          return (
            <li key={s.sourceId} className="inline-flex items-center gap-2">
              <svg width="22" height="6" aria-hidden="true">
                <line x1="0" y1="3" x2="22" y2="3" stroke={SOURCE_COLOR[s.sourceId]} strokeWidth="2.5" strokeDasharray={SOURCE_DASH[s.sourceId]} />
              </svg>
              <span className="text-muted">{nameOf(s.sourceId)}</span>
              <span className="font-medium text-gray-100 tabular-nums">{pct(v?.p, 1)}</span>
              {cursor === null && delta !== null && (
                <span className={`text-xs tabular-nums ${delta >= 0 ? 'text-dem' : 'text-rep'}`}>{pts(delta)} 30d</span>
              )}
            </li>
          );
        })}
      </ul>

      <div id={`${baseId}-panel`} role="tabpanel" aria-labelledby={`${baseId}-tab-${tab}`} ref={wrapRef} className="relative mt-4 w-full min-w-0 overflow-hidden">
        {geom ? (
          <svg
            width={width}
            height={H}
            role="img"
            tabIndex={0}
            aria-label={`Democratic ${tab} probability over time. Latest: ${label}. Use arrow keys to inspect dates.`}
            onPointerMove={onPointer}
            onPointerLeave={() => setCursor(null)}
            onKeyDown={onKey}
            onBlur={() => setCursor(null)}
            className="block touch-pan-y select-none"
          >
            {geom.yTicks.map((v) => (
              <g key={v}>
                <line x1={PAD.l} x2={width - PAD.r} y1={geom.y(v)} y2={geom.y(v)} stroke={v === 0.5 ? '#6b7280' : '#1f2937'} strokeDasharray={v === 0.5 ? '4 4' : undefined} />
                <text x={PAD.l - 6} y={geom.y(v)} dy="0.32em" textAnchor="end" fontSize="11" fill="#9ca3af">
                  {Math.round(v * 100)}%
                </text>
              </g>
            ))}
            {geom.xTicks.map((t) => (
              <text key={t} x={geom.x(t)} y={H - 6} textAnchor="middle" fontSize="11" fill="#9ca3af">
                {new Date(t * 1000).toLocaleDateString('en-US', { month: 'short', timeZone: 'UTC' })}
              </text>
            ))}
            {series.map((s) => (
              <path
                key={s.sourceId}
                d={s.points.map((p, i) => `${i ? 'L' : 'M'}${geom.x(p.t).toFixed(1)},${geom.y(p.p).toFixed(1)}`).join('')}
                fill="none"
                stroke={SOURCE_COLOR[s.sourceId]}
                strokeWidth="2"
                strokeDasharray={SOURCE_DASH[s.sourceId]}
                strokeLinejoin="round"
              />
            ))}
            {cursor !== null && (
              <g>
                <line x1={geom.x(cursor)} x2={geom.x(cursor)} y1={PAD.t} y2={H - PAD.b} stroke="#e5e7eb" strokeOpacity="0.5" />
                {readout.map(({ s, v }) =>
                  v ? <circle key={s.sourceId} cx={geom.x(v.t)} cy={geom.y(v.p)} r="4" fill={SOURCE_COLOR[s.sourceId]} stroke="#0a0e17" strokeWidth="2" /> : null,
                )}
              </g>
            )}
          </svg>
        ) : (
          <p className="py-16 text-center text-muted">No history available.</p>
        )}
        {geom && cursor !== null && (
          <div
            className="pointer-events-none absolute top-2 rounded-md border border-line bg-ink/95 px-2 py-1 text-xs text-gray-200 tabular-nums"
            style={{ left: Math.min(width - 90, Math.max(PAD.l, geom.x(cursor) + 8)) }}
          >
            {shortDate(cursor)}
          </div>
        )}
        <p className="sr-only" aria-live="polite">
          {announce}
        </p>
      </div>
    </section>
  );
}
